import { initTRPC } from '@trpc/server';

/**
 * Context shape provided to every procedure. The `userId` is extracted
 * from the `x-user-id` header by `createContext` in the App Router route.
 */
export interface Context {
  userId: string;
}

const t = initTRPC.context<Context>().create();

export const router = t.router;
export const publicProcedure = t.procedure;
export const createCallerFactory = t.createCallerFactory;

import { publicProcedure, router } from './init';

export const appRouter = router({
  getUser: publicProcedure.query(({ ctx }) => {
    return { userId: ctx.userId ?? 'anonymous' };
  }),
});

export type AppRouter = typeof appRouter;

import { fetchRequestHandler } from '@trpc/server/adapters/fetch';

import { appRouter } from '@/trpc/router';
import type { Context } from '@/trpc/init';

/**
 * Build the tRPC context for each incoming request.
 *
 * `fetchRequestHandler` passes the standard Web `Request` object as the
 * `req` argument, so we can read headers directly from it.
 */
const createContext = async (req: Request): Promise<Context> => {
  const userId = req.headers.get('x-user-id') ?? 'anonymous';
  return { userId };
};

const handler = (req: Request) =>
  fetchRequestHandler({
    endpoint: '/api/trpc',
    req,
    router: appRouter,
    createContext: () => createContext(req),
    onError:
      process.env.NODE_ENV === 'development'
        ? ({ path, error }) => {
            console.error(
              `❌ tRPC failed on ${path ?? '<no-path>'}: ${error.message}`,
            );
          }
        : undefined,
  });

export { handler as GET, handler as POST };

